<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';
import {api,systemApi,type SystemOverview,type SystemLogs,type CmsStatus} from '@/services/api';
import SystemOverviewDashboard from './SystemOverviewDashboard.vue';
import CmsDiscovery from './CmsDiscovery.vue';
import CmsConnectionReport from './CmsConnectionReport.vue';
import ServiceAddresses from './ServiceAddresses.vue';
import ServiceConfiguration from './ServiceConfiguration.vue';
const props=defineProps<{page:string}>();const emit=defineEmits<{connected:[base:string]}>();
const overview=ref<SystemOverview|null>(null),logs=ref<SystemLogs|null>(null),cms=ref<CmsStatus|null>(null);
const candidateReport=ref<CmsStatus|null>(null);
const sourceBusy=ref(false),discoveryBusy=ref(false);
const loading=ref(false),error=ref(''),message=ref(''),base=ref(''),filter=ref('all');
let generation=0;
const titles:Record<string,string>={'system-overview':'系统概览','system-config':'服务配置','system-source':'内容源与连接','system-domains':'App 接口与域名','system-logs':'日志查看'};
async function load(){const id=++generation;loading.value=true;error.value='';message.value='';try{const page=props.page;if(page==='system-overview'){const v=await systemApi.overview();if(id===generation)overview.value=v;}if(page==='system-logs'){const v=await systemApi.logs(filter.value);if(id===generation)logs.value=v;}if(page==='system-source'){const v=await api.cmsStatus();if(id===generation){cms.value=v;base.value=v.base;}}}catch(e){if(id===generation)error.value=(e as Error).message;}finally{if(id===generation)loading.value=false;}}
async function checkSource(save=false){if(sourceBusy.value||discoveryBusy.value||!base.value.trim())return;const id=++generation;sourceBusy.value=true;loading.value=false;error.value='';message.value='';try{if(save){const result=await api.cms(base.value.trim());if(id!==generation)return;cms.value=result.cmsStatus;candidateReport.value=result.cmsStatus;base.value=result.cmsStatus.base;emit('connected',result.cmsStatus.base);message.value='已通过真实接口检测，当前内容源已更新。';}else{const report=await api.checkCms(base.value.trim());if(id===generation)candidateReport.value=report;}}catch(e){if(id===generation){error.value=(e as Error).message;const report=(e as Error & {cmsStatus?:CmsStatus}).cmsStatus;if(report)candidateReport.value=report;}}finally{sourceBusy.value=false;}}
async function connected(value:string){if(props.page!=='system-source')return;emit('connected',value);await load();}
async function download(){try{error.value='';const v=await systemApi.logs(filter.value);logs.value=v;const blob=new Blob([JSON.stringify(v,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='hetun-audit-'+Date.now()+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=(e as Error).message;}}
watch(()=>props.page,load);onMounted(load);
</script>
<template><view class="system-page"><view v-if="!['system-overview','system-config'].includes(page)" class="system-heading"><view><text class="eyebrow">HETUN SYSTEM</text><text class="title">{{titles[page]}}</text><text class="muted">管理当前运营服务与客户端连接</text></view><button v-if="['system-overview','system-source','system-logs'].includes(page)" :disabled="loading||sourceBusy||discoveryBusy" @click="load">{{loading?'读取中…':'刷新数据'}}</button></view><text v-if="error" class="alert failure">{{error}}</text><text v-if="message" class="alert">{{message}}</text>
<SystemOverviewDashboard v-if="page==='system-overview'" :overview="overview" :loading="loading" @refresh="load"/>
<ServiceConfiguration v-if="page==='system-config'"/>
<view v-if="page==='system-source'" class="card form"><CmsConnectionReport :report="cms" title="当前内容源 · 已保存的连接" :checking="loading"/><CmsDiscovery :active-base="cms?.base||''" :disabled="sourceBusy" @busy="discoveryBusy=$event" @connected="connected"/><details><summary>手动连接其他 CMS</summary><text class="muted">输入站点域名即可检测，支持完整接口地址；只有保存成功才会切换当前内容源。</text><input v-model="base" :disabled="sourceBusy" placeholder="你的苹果CMS域名，或 https://域名/子目录"/><view class="actions"><button :disabled="sourceBusy||discoveryBusy||!base.trim()" @click="checkSource(false)">{{sourceBusy?'处理中…':'仅检测此地址'}}</button><button :disabled="sourceBusy||discoveryBusy||!base.trim()" @click="checkSource(true)">检测并保存连接</button></view><CmsConnectionReport v-if="candidateReport" :report="candidateReport" title="手动地址检测 · 保存后才生效" :checking="sourceBusy"/></details></view>
<view v-if="page==='system-domains'" class="card"><ServiceAddresses/></view>
<view v-if="page==='system-logs'" class="card"><view class="actions"><button v-for="f in [{id:'all',name:'全部'},{id:'system',name:'系统配置'},{id:'account',name:'管理员'},{id:'cms',name:'内容源'}]" :key="f.id" :class="{chosen:filter===f.id}" :disabled="loading" @click="filter=f.id;load()">{{f.name}}</button><button :disabled="loading" @click="download">下载当前日志</button></view><text class="muted">操作审计，每次最多读取最近 1 MB，显示最近 500 条；{{logs?.runtimeLogs||'服务运行日志在宝塔进程管理器查看'}}</text><text v-if="logs?.truncated" class="alert">日志超过读取范围，当前显示最近的匹配记录。</text><view class="log-row log-head"><text>时间</text><text>事件</text><text>修订</text></view><view v-for="(row,i) in logs?.items||[]" :key="i" class="log-row"><text>{{row.at}}</text><text>{{row.event}}</text><text>{{row.revision}}</text></view><text v-if="logs&&!logs.items.length" class="muted">当前分类暂无操作记录。</text></view>
</view></template>
<style scoped>
.system-page{padding:24px 0;overflow:auto;flex:1;min-height:0;color:var(--studio-text)}.system-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px;gap:20px}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--studio-muted)}.title{display:block;font-size:26px;font-weight:650;margin:8px 0}.muted{display:block;color:var(--studio-muted);font-size:12px;line-height:1.9;overflow-wrap:anywhere}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:18px}.panels{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{background:var(--studio-card);border:1px solid var(--studio-border);border-radius:16px;padding:24px;min-width:0}.card>text{display:block;overflow-wrap:anywhere;font-size:13px;line-height:1.9}.card .metric{font-size:25px;font-weight:650;margin:12px 0}.card .subtitle{font-size:17px;font-weight:600;margin-bottom:16px}button{font-size:12px;padding:10px 16px;background:var(--studio-input);color:var(--studio-text);border:1px solid var(--studio-border);border-radius:9px;margin:0}button[disabled]{opacity:.5}.alert{display:block;padding:12px 16px;border:1px solid var(--studio-border);border-radius:10px;background:var(--studio-input);margin-bottom:16px;font-size:13px}.failure{color:#e16c67}.good{color:#4aab80}.form>input,.form>textarea{box-sizing:border-box;display:block;width:100%;background:var(--studio-input);border:1px solid var(--studio-border);padding:12px;border-radius:8px;color:inherit;font-size:13px;margin:10px 0 16px;min-height:44px}.form>textarea{height:100px}.form>button{margin-top:20px}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:18px}.chosen{border-color:#65aa83;color:#65aa83}.log-row{display:grid;grid-template-columns:220px 1fr 80px;gap:16px;border-bottom:1px solid var(--studio-border);padding:14px 0;font-size:12px;overflow-wrap:anywhere}.log-head{color:var(--studio-muted)}@media(max-width:1200px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:800px){.system-page{padding:20px}.panels{grid-template-columns:1fr}.log-row{grid-template-columns:150px 1fr 40px}}
</style>
